import os
from collections.abc import Mapping
from typing import Any

import event_store
from signature_utils import verify_signature


REQUIRED_EVENT_FIELDS = ("event_id", "event_type", "account_id")


def _reject(reason: str) -> dict[str, Any]:
    return {"status": "rejected", "reason": reason}


def handle_webhook(request: Mapping[str, Any]) -> dict[str, Any]:
    """Validate and enqueue one payment event."""

    if not isinstance(request, Mapping):
        return _reject("malformed request")

    headers = request.get("headers", {})
    if headers is None:
        headers = {}
    if not isinstance(headers, Mapping):
        return _reject("malformed request")

    body = request.get("body", b"")
    if not isinstance(body, bytes):
        return _reject("malformed request")

    signature = headers.get("X-Webhook-Signature")
    if signature:
        secret = os.environ.get("WEBHOOK_SECRET", "")
        if not verify_signature(body, signature, secret):
            return _reject("invalid signature")

    try:
        event = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _reject("invalid json")

    if not isinstance(event, dict):
        return _reject("malformed event")
    if any(not isinstance(event.get(field), str) for field in REQUIRED_EVENT_FIELDS):
        return _reject("malformed event")

    event_store.append_event(event)
    return {"status": "accepted", "event_id": event["event_id"]}
